(x, y, t) => {
  const cx = 240, cy = 120;
  const w1x = Math.sin(x*0.018+t*0.25)*18 + Math.cos(y*0.013-t*0.18)*12;
  const w1y = Math.cos(y*0.02-t*0.22)*16 + Math.sin(x*0.016+t*0.3)*10;
  const w2x = Math.sin((x+w1y)*0.012+t*0.15)*10 + Math.cos((y+w1x)*0.01-t*0.12)*8;
  const w2y = Math.cos((y+w1x)*0.014-t*0.17)*9 + Math.sin((x+w1y)*0.011+t*0.2)*7;
  const sx = x + w1x + w2x, sy = y + w1y + w2y;
  const src = [
    [160+Math.sin(t*0.5)*110, 80+Math.cos(t*0.35)*55, 0.075, 2.1, 1.0],
    [320+Math.cos(t*0.45)*100, 160+Math.sin(t*0.6)*50, 0.09, 1.8, 0.9],
    [240+Math.sin(t*0.28+2)*150, 120+Math.cos(t*0.42+1)*95, 0.055, 2.4, 1.1],
    [100+Math.cos(t*0.7+1)*85, 190+Math.sin(t*0.55+3)*65, 0.11, 1.6, 0.85],
    [370+Math.sin(t*0.38+4)*95, 55+Math.cos(t*0.8+2)*75, 0.065, 2.7, 1.05],
    [200+Math.cos(t*0.32+5)*130, 210+Math.sin(t*0.5)*85, 0.085, 2.0, 0.95],
    [80+Math.sin(t*0.6+3)*70, 40+Math.cos(t*0.45+4)*50, 0.1, 1.4, 0.8],
    [400+Math.cos(t*0.33+1)*60, 200+Math.sin(t*0.48+2)*55, 0.07, 2.5, 1.15]
  ];
  let aS = 0, iS = 0, wS = 0;
  for (const [sX, sY, f, sp, wt] of src) {
    const d = Math.sqrt((sx-sX)**2 + (sy-sY)**2);
    aS += Math.sin(d*f - t*sp) * wt;
    iS += Math.sin(d*f*0.65 + t*sp*0.55 + 1.7) * wt;
    wS += Math.sin(d*f*1.4 - t*sp*0.8 + 2.5) * wt * 0.3;
  }
  const tw = src.reduce((s,v) => s+v[4], 0);
  aS /= tw; iS /= tw; wS /= tw;
  const n1 = Math.sin(sx*0.035+sy*0.022+t*0.7) + Math.sin(sx*0.028-sy*0.038+t*0.95);
  const n2 = Math.sin((sx+sy)*0.11+t*2.2)*0.3 + Math.sin((sx-sy)*0.09-t*1.8)*0.3;
  const n3 = Math.sin(sx*0.07+t*1.4)*Math.cos(sy*0.065-t*1.1)*0.4;
  const bg = (n1 + n2 + n3) / 2;
  const dist = Math.sqrt((sx-cx)**2 + (sy-cy)**2), ang = Math.atan2(sy-cy, sx-cx);
  const sp1 = Math.sin(dist*0.045-ang*3.5-t*1.3);
  const sp2 = Math.sin(dist*0.038+ang*4.5-t*1.0);
  const sp3 = Math.sin(dist*0.06-ang*2-t*1.8)*0.5;
  const spiral = (sp1+sp2+sp3) * 0.3;
  const diff = aS - iS*0.65 - wS*0.2;
  const feed = diff + bg*0.25 + spiral*0.35;
  const reaction = Math.tanh(feed * 2.0);
  const lap = Math.sin(sx*0.16)*Math.sin(sy*0.16) + Math.sin((sx+sy)*0.11+t)*0.45 + Math.sin(sx*0.22-t*0.5)*Math.cos(sy*0.19+t*0.4)*0.3;
  const cell = Math.tanh(lap * 1.4) * 0.28;
  const micro = Math.sin(sx*0.4+sy*0.35+t*3)*Math.cos(sx*0.3-sy*0.38-t*2.5)*0.08;
  const blend = reaction*0.65 + cell*0.25 + micro;
  const v = blend*0.5+0.5;
  const pal = [
    [6,12,52],[10,28,78],[14,55,98],[18,85,118],
    [28,120,128],[50,155,130],[110,175,115],
    [180,185,85],[210,175,65],[225,150,60],
    [215,120,65],[195,85,70],[160,55,68],
    [120,35,62],[75,22,58],[40,14,50],[6,12,52]
  ];
  const idx = v*(pal.length-1), i = Math.min(idx|0, pal.length-2), f = idx-i;
  const lum = 0.82 + Math.sin(reaction*Math.PI)*0.18;
  const edge = Math.abs(reaction)>0.65 ? 1.0 + (Math.abs(reaction)-0.65)*0.5 : 1.0;
  const glow = Math.max(0, 1.0-Math.abs(reaction)*1.5)*0.15;
  return [
    Math.min(255, ((pal[i][0]+(pal[i+1][0]-pal[i][0])*f)*lum*edge + glow*40)|0),
    Math.min(255, ((pal[i][1]+(pal[i+1][1]-pal[i][1])*f)*lum*edge + glow*60)|0),
    Math.min(255, ((pal[i][2]+(pal[i+1][2]-pal[i][2])*f)*lum*edge + glow*80)|0)
  ];
}
